import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def pipeline(*cmds):
  """Run the commands as a pipe of the shell. When the last command fails,
  stop the task with its code, as set -e does without pipefail."""
  sys.stdout.flush()
  procs = []
  prev = None
  for i, cmd in enumerate(cmds):
    last = i == len(cmds) - 1
    proc = subprocess.Popen(cmd, stdin=prev, stdout=None if last else subprocess.PIPE)
    if prev is not None:
      prev.close()
    prev = proc.stdout
    procs.append(proc)
  rc = [proc.wait() for proc in procs][-1]
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  helpers.print_header("Getting default gateway ...")
  pipeline(["route", "-n", "get", "default"], ["grep", "gateway"], ["awk", "{ print $2 }"])


if __name__ == "__main__":
  main()
